// Proactive message gate. Never sends; only decides.
import { mkdirSync } from 'node:fs';

const MIN_DATA_POINTS = 3;     // fewer observations: not enough to say anything
const MIN_CONFIDENCE = 0.6;    // lower confidence: not worth showing
const HOUR_MIN_SAMPLES = 5;    // earlier messages needed before an hour counts as bad
const HOUR_DISMISS_RATIO = 0.7; // push held in an hour where this share was dismissed

const hold = (reason) => ({ send: false, surfaces: [], reason });
const enc = (s) => encodeURIComponent(String(s));

export async function decide({ user, candidate, context, now } = {}) {
  const dir = process.env.STATE_DIR;
  if (!dir) return hold('No state directory is configured, so nothing is shown.');
  mkdirSync(dir, { recursive: true });

  const uid = user?.id;
  const cid = candidate?.id;
  if (uid == null || cid == null) return hold('The user or message id is missing, so nothing is shown.');
  const ms = now instanceof Date ? now.getTime() : NaN;
  if (!Number.isFinite(ms)) return hold('The current time is unknown, so nothing is shown.');

  // Redelivery: an id already delivered gets the same answer, nothing is spent twice.
  const idKey = `msg-${enc(uid)}-${enc(cid)}`;
  const prior = await gkRead(dir, idKey);
  if (prior && prior.send) return { send: true, surfaces: prior.surfaces, reason: null };

  if (context?.crisis === true) return hold('The user is in a crisis, so no proactive message is shown.');

  const zone = user.timezone;
  if (typeof zone !== 'string' || !gkZoneOk(zone)) return hold('The user time zone is unknown or invalid, so nothing is shown.');

  const ins = candidate.insight;
  if (!ins || ins.key == null) return hold('The finding has no key, so nothing is shown.');
  if (!(Number(ins.dataPoints) >= MIN_DATA_POINTS)) return hold(`The finding rests on fewer than ${MIN_DATA_POINTS} observations, so it is not worth showing.`);
  if (!(Number(ins.confidence) >= MIN_CONFIDENCE)) return hold('The finding is not confident enough to be worth showing.');

  // Interrupting surface (push) rules; in-app stays silent and allowed.
  let push = true;
  if (user.focusMode === true) push = false;
  const hs = context?.hourStats?.[String(gkLocal(ms, zone).hour)];
  if (hs) {
    const acted = Number(hs.acted) || 0, dismissed = Number(hs.dismissed) || 0;
    if (acted + dismissed >= HOUR_MIN_SAMPLES && dismissed / (acted + dismissed) >= HOUR_DISMISS_RATIO) push = false;
  }

  // Same finding: shown once per recipient-local day.
  const day = gkDayKey(ms, zone);
  const insKey = `ins-${enc(uid)}-${enc(ins.key)}-${day}`;
  if (!(await gkClaim(dir, insKey))) return hold('This finding was already shown to the user today.');
  if (!(await gkClaim(dir, idKey + '-claim'))) {
    await gkUnclaim(dir, insKey);
    const again = await gkRead(dir, idKey);
    if (again && again.send) return { send: true, surfaces: again.surfaces, reason: null };
    return hold('This message is already being handled.');
  }
  const surfaces = push ? ['push', 'inApp'] : ['inApp'];
  await gkWrite(dir, idKey, { send: true, surfaces, at: ms });
  return { send: true, surfaces, reason: null };
}
EOF
